  VALUES 
    (247::BIGINT, 'De los mejores profes de la escuela, matricule sin miedo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'c26ed575a92c3b9bfcaf0650f534230c7268eb089c96de4653dcdba485c47500'::TEXT, ARRAY[954]::BIGINT[]),
    (247::BIGINT, 'Excelente profesor, hace que las clases sean interesantes y explica muy bien. Además, responde las dudas por teams muy rápido. El único problema del curso en verano es que la evaluación fue 100% exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2026-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'a7ff1c8db82b1c2f0e23cf636d9c146a1a63a8c9fdba7fae31f9eb37005bb984'::TEXT, ARRAY[3062]::BIGINT[]),
    (247::BIGINT, 'Poco social y vacío existencial mente'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-21T00:00:00+00:00'::TIMESTAMPTZ, '4f6ad953234aee1d24142cbaaaa2d7cca54acf6935d67f9e4986d74b6a59c3a4'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Sin temor a equivocarme, es el mejor profe de toda la escuela, ayuda muchísimo y las evaluaciones son sencillas, además se aprende muchísimo con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'f0ea608943c0a2f8c6ce7d01f7e305a43b2d98d07dd517ce27f194d7cb2c970c'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Excelente profesor, va a aprender demasiado con él. Las asignaciones son son sencillas, siempre ayuda en las consultas que le haga y responde súper rápido. De lo mejor de la escuela.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'efb11263950cb0fa251e85e964f415ff2c8c1dfd195870132991f0279602de83'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Como diria él, "hagaselo sencilo" y matricule con Garro sin miedo al exito. El mejor profe, se preocupa mucho por que entiendas y si le pides ayuda en consulta, él estará atento, a culquer hora contesta!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2023-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'af09d64fea6a4e0ebfd42fd36b63c9949591e1ee38eafa4a945a205c29afdd6e'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Uno de los mejores profes de la escuela. Aprovechen mucho sus clases porque van a aprender demasiado. Su único interés es que uno aprenda en el curso, así que no es mal intencionado con exámenes o trabajos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '1cf302f8dde7ae53eefe3d0f50d6e3234a1338fea21625740de32813d597da95'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Las clases son excelentes, las hace muy entretenidas y es una excelente persona. Las evaluaciones por otra parte son muy fáciles, los examenes se basan en hacer los cálculos de los laboratorios y preguntas sobre la materia vista en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '30c373d30ecd2da83d4b3977757ef8949dad8b470f79c585d37a9762f7b8f1f5'::TEXT, ARRAY[3063]::BIGINT[]),
    (247::BIGINT, 'Es muy buena nota y ayuda bastante, se preocupa porque uno aprenda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'd76fa9131fe3b13b4096b2eb16c3802a5133a832ecc3434c50df5c0d42e4ab08'::TEXT, ARRAY[1007]::BIGINT[]),
    (247::BIGINT, 'El mejor profe, ojala el resto de los profes de la escuela fueran como el, pero no son una basura todos, disfruten al maximo las clases con el porque no hay ninguno mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-10-31T00:00:00+00:00'::TIMESTAMPTZ, '945aafd27664978568c860f1e5c269c9636157a440a03d267cc68f2e41998d75'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Es el mejor profe de toda la escuela. Hace las clases muy entretenidas, se interesa mucho por el aprendizaje de los estudiantes y las evaluaciones son fáciles porque explica muy bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-09-24T00:00:00+00:00'::TIMESTAMPTZ, '043a1de57a970cf23f48e809478409bfa52943b8c2f8d873d600e0ae15076432'::TEXT, ARRAY[956, 970]::BIGINT[]),
    (247::BIGINT, 'Es buen profe y buena persona. Atiende mucho las consultas hasta fines de semana u horas tarde, la evaluación es pesada en proyectos, lo demás es sencillo. Se enfoca en que el estudiante domine el tema y sepa de qué está hablando, con las presentaciones es un poco desordenado, pero se entienden.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '101c75420656cfca438db26180b5758327bf163fc8417d350b0fccd679cd159d'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Las clases son excelentes, las hace muy entretenidas y es una excelente persona. Las evaluaciones por otra parte son muy fáciles, incluso parece que no revisa algunas y pone simplemente el 100.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, '599ded760bd04d4100e7a28430c460462a7b7d77345e2fb388ae741d7131cf59'::TEXT, ARRAY[3063]::BIGINT[]),
    (247::BIGINT, 'Un pro, no tiene mejor opción en la escuela para cursos del area.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'e2fcf1400263cad6869f2eb2266c07ea5fdc369c5fcfd8d7612da658ee8be260'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Muy buen profe hace la clase muy amena y vacilona, un crack.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, '44ad1bf2f1799223481e313f5da24699bd0632de97d80ae18cdec68bc135cf06'::TEXT, ARRAY[1224]::BIGINT[]),
    (247::BIGINT, 'De los mejores profes de electromecánica!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-16T00:00:00+00:00'::TIMESTAMPTZ, '1dac3f8c47b50baf6f166c10f09370f648ca3c9859ffad10e3c060e0cb4c125a'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Explica muy bien y las evaluaciones no son complicadas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-17T00:00:00+00:00'::TIMESTAMPTZ, '09ffca7593d24a99ecb5fb4fbb54202a2a1b431469ade89a0aec09c21c8234b7'::TEXT, ARRAY[3063]::BIGINT[]),
    (247::BIGINT, 'Uno de los mejores profes que he tenido, las clases son largas pero entretenidas, hace que uno se apasione por la materia, lástima que solo da un curso por no ser de la carrera. Ayuda demasiado, es super buena nota.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, '3d78e59e8ade72544e3c98ca5ce18322b4c676c662a8d54a0ec23a5e9644ef49'::TEXT, ARRAY[1224]::BIGINT[]),
    (247::BIGINT, 'De los mejores profes de la escuela. Excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a23703fb3b07e96f704f3fea866d2d299676bfe68361f7406577b9b9c76fd5ec'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'El 100% del curso es lo que dice el profe en clase. Ahora, las clases no se graban, sino que en youtube están las clases de semestres anteriores . Ahora el profe es muy olvidadizo, con esto, es su palabra con la del profe, es decir perdió los puntos.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ed63cc897482a38ce631466b0fee4ce3d097b7011a27efe3826e52a4838f137a'::TEXT, ARRAY[1007]::BIGINT[]),
    (247::BIGINT, 'poco aesertivo indifrente y vacio'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, '543a0eb34cdb9c88a67694a2470672a2c4ac3c0042ec342f8079662da514cb0f'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Excelente profesor. Totalmente dedicado a su trabajo, responde cualquier pregunta rápido y se esfuerza al máximo hasta que uno entienda la duda. Las clases son excelentes, prácticamente si uno pone atención ya queda listo para las evaluaciones. Tiene canal de YT para volver a ver las clases!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '32d8f8e8b3726bf19480bf0df51044060462518f1d71b11183fcd26aeac95bd5'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Excelente profesor, dispuesto a ayudar y se le nota la vocación como profesor e ingeniero. Sabe mucho y de verdad se notan las ganas de que el estudiante aprenda dando todo el material claro, se notó mucho el esfuerzo que le puso al curso al ser virtual.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '83835db8434e7bf4be3befff624eb97a022054251cd27defed7f09195c34a336'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Es muy respetuoso y todo lo repite demasiadas veces. A veces se le olvida explicar en clases materia que es fundamental para los proyectos, pero en consulta es excelente y flexible. De verdad tiene vocación como profesor e ingeniero.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'a9d84eaea6d2e3df751b273759118ed91a20ca2091435054b6129b31bc8728eb'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Un excelente profe, explica la materia de forma clara y sencilla, además de que se preocupa que los estudiantes tengan todo el material para realizar los labs, muy recomendado, se pasa fácil y se aprende mucho con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, '99ba5312a35be2a8b4661ddbdff78c31691d49c00c8c66649b28ca4007eb4409'::TEXT, ARRAY[956]::BIGINT[]),
    (247::BIGINT, 'Un gran profesional y una gran persona, el profe sabe demasiado, siempre está dispuesto a dar consejos, a corregir de manera respetuosa, a explicar una y otra vez, el mejor profesor de la Escuela..'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-01-07T00:00:00+00:00'::TIMESTAMPTZ, '8b32db2e215838fa05b5288e6dbe65fd8843de30a10cca19e752f4149eaf7703'::TEXT, ARRAY[970]::BIGINT[]),
    (247::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Brinda apoyo']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '38f084aca71f9aeb7ff4937ba7671410ab8bb5ecad04aff4782d17e45dce07a6'::TEXT, ARRAY[1224]::BIGINT[]),
    (247::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2019-11-01T00:00:00+00:00'::TIMESTAMPTZ, 'fd3a7a5940cc556dd9cfd4a84d87be46ce63395829c269a191118d37ba327c92'::TEXT, ARRAY[1224]::BIGINT[]),
    (247::BIGINT, 'Uno de los mejores profes de la escuela, sabe muchisimo de lo que habla y es super pura vida. De fijo lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '85999f7e92d5f44889f3626f85fc10ef02e11cabee877a87abd241e3f49e496c'::TEXT, ARRAY[956]::BIGINT[]),
    (247::BIGINT, 'Excelente profesor. Clases entretenidas y la materia queda muy clara. La dificultad de las evaluaciones corresponde con el nivel del curso y lo visto en clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '206bdbf48518bfae786f49b9df702d31ceb3f169c1381a96be3d38d3ea6dfb52'::TEXT, ARRAY[954]::BIGINT[]),
