    (247::BIGINT, 'Excelente Profesor!!!! sin duda :D califica normal/suave, las tareas son de 100, y explica muy bien!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'e33e38d3e0df7b5ae8c565edcc7951b6bbab6b1e15973ef927e0ddd2176bbb78'::TEXT, ARRAY[954]::BIGINT[]),
