    (247::BIGINT, 'El profe explica super bien toda la materia, no hace falta tocar nunca un libro del curso que es algo que no cualquier profesor logra. Solo se necesita poner atención en clases y tomar TODOS los apuntes del caso. Con el cuaderno entendido y las tareas que deja para los examenes es suficiente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, '0eac13f95168ff4982346519863f7ca9ffdafc31d947a307af15da24da6a68b8'::TEXT, ARRAY[954]::BIGINT[]),
    (247::BIGINT, 'Excelencia de profesor'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-24T00:00:00+00:00'::TIMESTAMPTZ, '989d6984458a02c484a25af707ee6da89f4200a4b3059cd1c1c09ad11f0bdf26'::TEXT, ARRAY[3062]::BIGINT[]),
    (247::BIGINT, 'Calidad de profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-23T00:00:00+00:00'::TIMESTAMPTZ, 'bc5c02b8bd52e2917027559c40c30219b2405f631b8a57c369a92ba8ca5cfd0d'::TEXT, ARRAY[970]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
